msgbox	PLAYER erhielt den KNOCHENORDEN von BRAWLY.
waitmessage
call Common_EventScript_PlayGymBadgeFanfare
msgbox	Der KNOCHENORDEN sorgt dafür, dass dir alle POKéMON bis Level 30, auch getauschte, ohne Widerrede gehorchen.Außerdem kannst du die VM-Attacke BLITZLICHT außerhalb von Kämpfen einsetzen.Wenn du möchtest, nimm auch diese TECHNISCHE MASCHINE.
setflag FLAG_DEFEATED_DEWFORD_GYM
setflag FLAG_BADGE02_GET
addvar VAR_PETALBURG_GYM_STATE 1
call_if_eq VAR_PETALBURG_GYM_STATE 6 Common_EventScript_ReadyPetalburgGymForBattle
